components.css:
.ds-article-header{background:var(--cover,#d6e5f7);color:var(--ink,#132646);padding:32px 32px 40px;font-family:var(--sans,'Hanken Grotesk',sans-serif);line-height:1.5}.ds-article-inner{max-width:960px;margin-inline:auto}.ds-back{display:inline-flex;align-items:center;gap:7px;min-height:44px;margin-bottom:24px;color:var(--link,#244dcc);text-decoration:none;font-size:15px}.ds-back-arrow{width:20px;height:20px;flex-shrink:0;transform:rotate(180deg)}.ds-back:hover{text-decoration:underline;text-underline-offset:.2em;text-decoration-thickness:1px}.ds-back:focus-visible{outline:2px solid var(--link,#244dcc);outline-offset:6px;border-radius:2px}.ds-article-header h1{margin:0;font-family:var(--display,'Hanken Grotesk',sans-serif);font-size:40px;font-weight:700;line-height:1.15;letter-spacing:-.025em;max-width:24ch;text-wrap:balance}.ds-meta{display:flex;flex-wrap:wrap;align-items:center;gap:8px 20px;font-size:14px;color:var(--secondary,#43536c);margin-top:20px}.ds-meta time{font-variant-numeric:tabular-nums}@media(max-width:900px){.ds-article-header{padding-top:24px;padding-bottom:40px}.ds-back{margin-bottom:24px}}@media(max-width:540px){.ds-article-header{padding-inline:24px}.ds-article-header h1{font-size:32px}.ds-meta{gap:7px 16px}}@media(max-width:360px){.ds-article-header{padding-inline:20px}}.ds-visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.ds-article-header.ds-compact { padding-block: 16px; }
.ds-compact .ds-article-inner { max-width: var(--reading-width, 640px); display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 24px; }
.ds-compact .ds-back { margin-bottom: 0; }
.ds-compact .ds-meta { margin-top: 0; }
